// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
/** Drinking mode: pure bookkeeping for sip cards. Nobody is ever asked for more than the caps below. */
export const ROUND_CAP = 3, GAME_CAP = 10;

/** A call's `to` for the whole table. A seat with exactly this name is refused while drinking is on (startRoom). */
export const GROUP_CALL = "all";
export type DrinkCall = { to: string | typeof GROUP_CALL; sips: number; reason: string; handsOut?: boolean; water?: boolean };
export type DrinkState = { totals: Record<string, number>; calls: DrinkCall[]; seq: number; watered: string[] };

export const initDrinks = (players: string[]): DrinkState => ({ totals: Object.fromEntries(players.map((p) => [p, 0])), calls: [], seq: 0, watered: [] });

const sipsOf = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(ROUND_CAP, Math.floor(n))) : 0);

/**
 * Starts a new round of cards: `calls` is replaced and `seq` goes up so the UI replays. Each call is trimmed so
 * nobody drinks more than ROUND_CAP this round or GAME_CAP overall. A player who reaches the game cap gets one
 * water card, once. Handing out sips counts for nobody; a group toast only reaches players still under the cap.
 */
export function addCalls(d: DrinkState, calls: DrinkCall[], players: string[]): DrinkState {
  const totals = { ...d.totals };
  const watered = [...d.watered];
  const round: Record<string, number> = {};
  const out: DrinkCall[] = [];
  const water: DrinkCall[] = [];

  /** How many of `want` sips this player can still take; records them. */
  const take = (p: string, want: number) => {
    const n = Math.min(want, ROUND_CAP - (round[p] ?? 0), GAME_CAP - (totals[p] ?? 0));
    if (n <= 0) return 0;
    round[p] = (round[p] ?? 0) + n;
    totals[p] = (totals[p] ?? 0) + n;
    if (totals[p]! >= GAME_CAP && !watered.includes(p)) {
      watered.push(p);
      water.push({ to: p, sips: 0, reason: "Water counts. You're done for the night.", water: true });
    }
    return n;
  };

  for (const c of calls) {
    const want = sipsOf(c.sips);
    if (want <= 0) continue;
    if (c.handsOut) {
      if (players.includes(c.to)) out.push({ ...c, sips: want });
    } else if (c.to === GROUP_CALL) {
      let shown = 0;
      for (const p of players) shown = Math.max(shown, take(p, want));
      if (shown > 0) out.push({ ...c, sips: shown });
    } else if (players.includes(c.to)) {
      const n = take(c.to, want);
      if (n > 0) out.push({ ...c, sips: n });
    }
  }
  return { totals, calls: [...out, ...water], seq: d.seq + 1, watered };
}
